    "kind": "eev",
    "spec": "No ohm figure in this manual. Check No.12: continuity between pins 5-1, 5-2, 5-3, 5-4; no continuity = EV coil faulty.",
    "test": "Power off and back on and listen for each EV to latch (click). For one that does not, unplug it and check continuity pins 5-1, 5-2, 5-3, 5-4 (pin 5 common). No continuity = bad coil. Continuity OK: swap in a good coil - if it then clicks the PCB is bad, if not the valve body is bad. If no EV clicks at all, the outdoor PCB is bad.",
