    "name": "EEV coil (electronic expansion valve)",
    "location": "On the outdoor unit's expansion valve body; coil lead plugs into S20 on the main PCB (5-pin)",
    "kind": "eev",
    "spec": "No ohm value is printed. Manual (Check No.12): 'Check the continuity between the pins 5 - 1, 5 - 2, 5 - 3, 5 - 4 ... If there is no continuity between the pins, the EV coil is faulty.' (5P connector)",
    "test": "Check the S20 plug is seated. Power off then on - the valve should make a latching/clicking sound. If not, power off, unplug S20 and check continuity from the common pin to each of the 4 phase pins. No continuity on any pair = bad EEV coil. Continuity on all = replace the main PCB.",
